const {readdirSync,readFileSync,existsSync}=require("fs");
const dir=".sofar/initiatives";
const slugs=readdirSync(dir).filter(s=>existsSync(`${dir}/${s}/events.jsonl`));
const decisionsBy={},tasksBy={};
for(const slug of slugs){
  const evs=readFileSync(`${dir}/${slug}/events.jsonl`,"utf8").split("\n").filter(l=>l.trim())
    .map(l=>{try{return JSON.parse(l)}catch{return null}}).filter(Boolean).sort((a,b)=>a.id<b.id?-1:1);
  decisionsBy[slug]=evs.filter(e=>e.type==="decision_logged");
  const t=new Set();
  for(const e of evs){ if(e.type==="plan_updated") for(const ph of e.payload.plan.phases) for(const x of ph.tasks) t.add(x.id); if(e.type==="task_added")t.add(e.payload.id); }
  tasksBy[slug]=t;
}
const slugAlt=slugs.slice().sort((a,b)=>b.length-a.length).join("|");
// QUALIFIED: <slug> <D n | T n | n.n>   UNQUALIFIED: D<n> | T<n> only (no bare dotted ids)
const QUAL=new RegExp(`\\b(${slugAlt})\\s+(D\\d+|T\\d+|\\d+\\.\\d+)\\b`,"g");
const UNQUAL=/\b(D\d+|T\d+)\b/g;
let rd=0,rt=0,dang=0,self=0,future=0,total=0; const dc=new Map(), edges=[];
for(const slug of slugs) decisionsBy[slug].forEach((d,idx)=>{
  const text=[d.payload.chose,d.payload.over,d.payload.because].join("\n");
  const seen=new Set(); const cites=[];
  for(const m of text.matchAll(QUAL)){ cites.push([m[1],m[2],m[0]]); seen.add(m.index); for(let i=m.index;i<m.index+m[0].length;i++) seen.add(i); }
  for(const m of text.matchAll(UNQUAL)){ if(seen.has(m.index)) continue; cites.push([slug,m[1],m[0]]); }
  for(const [home,h,raw] of cites){
    total++;
    let target=null;
    if(/^D\d+$/.test(h)){ const n=+h.slice(1); const arr=decisionsBy[home]; if(arr&&n>=1&&n<=arr.length) target=arr[n-1].id; }
    else { if(tasksBy[home]&&tasksBy[home].has(h)) target=`task:${home}#${h}`; }
    if(!target){ dang++; dc.set(raw,(dc.get(raw)||0)+1); continue; }
    if(target===d.id){ self++; continue; }
    if(target.startsWith("01")&&target>d.id){ future++; continue; }
    if(h.startsWith("D")) rd++; else rt++;
    edges.push([slug,home]);
  }
});
console.log(`handle tokens: ${total}  -> decision:${rd} task:${rt} self:${self} future:${future} dangling:${dang}`);
console.log("dangling (top):",[...dc.entries()].sort((a,b)=>b[1]-a[1]).slice(0,14).map(([k,c])=>`${k}=${c}`).join(" "));
const cross=edges.filter(([a,b])=>a!==b);
console.log(`resolved edges: ${edges.length}, CROSS-initiative: ${cross.length}`);
const byTarget=new Map();
for(const [from,to] of cross){ const s=byTarget.get(to)||new Set(); s.add(from); byTarget.set(to,s); }
console.log("cited-from-elsewhere targets:",[...byTarget.entries()].map(([t,s])=>`${t}<-{${[...s].join(",")}}`).join("  "));
